--
-- Estructura de tabla para la tabla `security_rules`
--

CREATE TABLE `security_rules` (
  `id` int(11) NOT NULL,
  `provider` varchar(20) NOT NULL,
  `service` varchar(50) DEFAULT NULL,
  `check_id` varchar(100) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `severidad_id` int(11) NOT NULL,
  `condition_logic` text DEFAULT NULL,
  `remediation` text DEFAULT NULL,
  `reference` text DEFAULT NULL,
  `actualizacion` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `display_name` varchar(255) DEFAULT NULL,
  `creado_por_ia` tinyint(1) NOT NULL DEFAULT 0,
  `origen` varchar(20) DEFAULT '''manual''',
  `validado_por` int(11) DEFAULT NULL,
  `validado_at` datetime DEFAULT NULL,
  `creacion` datetime DEFAULT current_timestamp(),
  `estado_id` int(11) DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Volcado de datos para la tabla `security_rules`
--

INSERT INTO `security_rules` (`id`, `provider`, `service`, `check_id`, `title`, `description`, `severidad_id`, `condition_logic`, `remediation`, `reference`, `actualizacion`, `display_name`, `creado_por_ia`, `origen`, `validado_por`, `validado_at`, `creacion`, `estado_id`) VALUES
(801, 'aws', 'accessanalyzer', 'accessanalyzer_enabled', 'IAM Access Analyzer is enabled', '**IAM Access Analyzer** presence and status are evaluated per account and Region. An analyzer in `ACTIVE` state indicates continuous analysis of supported resources and IAM activity to identify external, internal, and unused access.', 2, NULL, 'Enable **IAM Access Analyzer** across all accounts and active Regions (*or organization-wide*). Operate on least privilege: continuously review findings, remove unintended access, and trim unused permissions. Use archive rules sparingly, integrate reviews into change/CI/CD workflows, and enforce separation of duties on policy changes.', 'https://hub.prowler.com/check/accessanalyzer_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(818, 'aws', 'awslambda', 'awslambda_function_env_vars_not_encrypted_with_cmk', 'Lambda function environment variables are encrypted with a customer-managed KMS key', '**AWS Lambda function** environment variables are encrypted at rest using a **customer-managed KMS key (CMK)** rather than the default AWS-managed Lambda service key.\n\nThe presence of a `KMSKeyArn` on the function configuration indicates CMK-based encryption is active.', 3, NULL, 'Encrypt Lambda environment variables with a customer-managed KMS key to maintain full control over key lifecycle and access.\n- Create a dedicated KMS key per application or per function for blast-radius isolation\n- Enable **automatic key rotation** (`EnableKeyRotation: true`)\n- Grant only the Lambda execution role decrypt access via a key policy condition on `kms:ViaService`\n- Prefer **AWS Secrets Manager** or **SSM Parameter Store (SecureString)** for secrets — environment variables should hold', 'https://hub.prowler.com/check/awslambda_function_env_vars_not_encrypted_with_cmk', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(822, 'aws', 'awslambda', 'awslambda_function_inside_vpc', 'Lambda function is deployed inside a VPC', '**AWS Lambda function** uses **VPC networking** with specified subnets and security groups, rather than the default Lambda-managed network.\n\nPresence of a VPC association (`vpc_id`) indicates private connectivity to VPC resources.', 2, NULL, 'Attach functions to a VPC with private subnets and restrictive security groups to enforce **least privilege** and egress control.\n- Prefer **VPC endpoints** for AWS services\n- Use NAT only when necessary\n- Spread subnets across AZs for resilience\n- Govern with IAM conditions requiring `VpcIds`, `SubnetIds`, and `SecurityGroupIds`.', 'https://hub.prowler.com/check/awslambda_function_inside_vpc', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(826, 'aws', 'awslambda', 'awslambda_function_invoke_api_operations_cloudtrail_logging_enabled', 'Lambda function Invoke API calls are recorded by CloudTrail', '**AWS Lambda** function invocations are recorded as **CloudTrail data events** when trails include `AWS::Lambda::Function` resources.\n\nThe finding reflects whether a function\'s `Invoke` activity is being logged by an eligible trail.', 2, NULL, 'Enable **CloudTrail data event logging** for `AWS::Lambda::Function` to capture `Invoke` calls across required Regions and accounts. Apply **least privilege** selectors to scope events, centralize logs with strong retention, and integrate alerts for anomalous invokes as part of **defense in depth**.', 'https://hub.prowler.com/check/awslambda_function_invoke_api_operations_cloudtrail_logging_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(830, 'aws', 'awslambda', 'awslambda_function_no_dead_letter_queue', 'Lambda function has a Dead Letter Queue configured', '**AWS Lambda functions** have a **Dead Letter Queue (DLQ)** configured — an SQS queue or SNS topic that receives records of failed asynchronous invocations.\n\nWithout a DLQ, failed invocations are silently discarded after exhausting retries.', 3, NULL, 'Configure a Dead Letter Queue for every Lambda function that handles asynchronous invocations.\n- Prefer an **SQS queue** as the DLQ target for retry and replay capability\n- Ensure the Lambda execution role has `sqs:SendMessage` permission on the DLQ\n- Monitor DLQ depth with a CloudWatch alarm to alert on processing failures', 'https://hub.prowler.com/check/awslambda_function_no_dead_letter_queue', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(834, 'aws', 'bedrock', 'bedrock_guardrails_configured', 'Bedrock has at least one guardrail configured in the audited region', '**Amazon Bedrock guardrails** provide reusable safety policies for filtering harmful or unwanted content in model inputs and outputs.\n\nThis evaluation checks whether at least one guardrail exists in each successfully scanned region. It does **not** verify that guardrails are attached to agents or passed on individual model invocation API calls.', 3, NULL, 'Create at least one **Bedrock guardrail** in each region where Bedrock is used, then separately ensure those guardrails are attached to relevant agents and invocation paths.\n- Configure **content filters** for harmful categories (hate, violence, sexual, misconduct)\n- Add **sensitive information filters** and **denied topic policies**\n- Apply guardrails at the API call level using `guardrailIdentifier` where supported', 'https://hub.prowler.com/check/bedrock_guardrails_configured', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(836, 'aws', 'bedrock', 'bedrock_model_invocation_logging_enabled', 'Amazon Bedrock model invocation logging is enabled', '**Bedrock** model invocation logging captures request, response, and metadata for `Converse`, `ConverseStream`, `InvokeModel`, and `InvokeModelWithResponseStream` calls per Region, delivering records to **CloudWatch Logs** and/or **S3** when configured.', 3, NULL, 'Enable **model invocation logging** and route events to **CloudWatch Logs** and/or **S3**.\n\nEnforce **least privilege** on log access, use encryption, and set retention/lifecycle policies. Monitor for anomalies and alerts to support **defense in depth** and **separation of duties**.', 'https://hub.prowler.com/check/bedrock_model_invocation_logging_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(838, 'aws', 'bedrock', 'bedrock_prompt_management_exists', 'Amazon Bedrock Prompt Management prompts exist in the region', '**Bedrock Prompt Management** enables centralized creation, versioning, and governance of prompts used with foundation models.\n\nThis region-level check verifies whether at least one managed prompt exists in each scanned region, used as an adoption signal for Prompt Management. The presence of a prompt does not by itself guarantee that every application prompt is managed.', 2, NULL, 'Adopt **Bedrock Prompt Management** to centralize prompt definitions, enforce versioning, and maintain governance over model interactions.\n\nUse managed prompts with **guardrails** and apply **least privilege** access controls to restrict who can create or modify prompts.', 'https://hub.prowler.com/check/bedrock_prompt_management_exists', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(839, 'aws', 'cloudformation', 'cloudformation_stacks_termination_protection_enabled', 'CloudFormation stack has termination protection enabled', '**AWS CloudFormation root stacks** are evaluated for **termination protection**. The detection identifies whether `termination protection` is enabled to block stack deletions on non-nested stacks.', 3, NULL, 'Enable **termination protection** on root stacks for critical workloads. Enforce **least privilege** on who can alter this setting or delete stacks, require **change review** via change sets, and apply **stack policies** plus `DeletionPolicy: Retain` for data stores for defense in depth.', 'https://hub.prowler.com/check/cloudformation_stacks_termination_protection_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(853, 'aws', 'cloudtrail', 'cloudtrail_cloudwatch_logging_enabled', 'CloudTrail trail has delivered logs to CloudWatch Logs in the last 24 hours', '**CloudTrail trails** are configured to send events to **CloudWatch Logs**, and show recent delivery within the last `24h`. Trails without integration or without recent CloudWatch delivery are identified, across single-Region and multi-Region trails.', 2, NULL, 'Integrate every trail with **CloudWatch Logs** and maintain continuous, near-real-time delivery. Enforce **least privilege** on the delivery role, prefer **multi-Region** coverage, and implement **metric filters and alerts** for sensitive actions. Centralize retention to support **defense in depth**.', 'https://hub.prowler.com/check/cloudtrail_cloudwatch_logging_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(854, 'aws', 'cloudtrail', 'cloudtrail_insights_exist', 'CloudTrail trail has Insights enabled', '**CloudTrail trails** that are logging are evaluated for **Insights** via `insight selectors`, which enable anomaly detection on management-event patterns (API call and error rates). The finding pinpoints logging trails where these selectors are missing.', 2, NULL, 'Enable **CloudTrail Insights** on all logging trails (ideally all-Region or organization trails). Activate both `ApiCallRateInsight` and `ApiErrorRateInsight`. Integrate alerts with monitoring and review anomalies regularly. Apply **defense in depth** and least privilege to reduce potential blast radius.', 'https://hub.prowler.com/check/cloudtrail_insights_exist', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(856, 'aws', 'cloudtrail', 'cloudtrail_kms_encryption_enabled', 'CloudTrail trail logs are encrypted at rest with a KMS key', '**AWS CloudTrail trails** are evaluated for use of **SSE-KMS** with a customer-managed KMS key to encrypt delivered log files at rest in S3. Trails without a configured KMS key are identified. *Applies to single-Region and multi-Region trails.*', 3, NULL, 'Enable **SSE-KMS** on every trail using a **customer-managed KMS key**. Apply **least privilege** so only authorized roles can `Decrypt`, and enforce **separation of duties** between key admins and log readers. Rotate keys and monitor key usage to provide **defense in depth** for CloudTrail data.', 'https://hub.prowler.com/check/cloudtrail_kms_encryption_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(857, 'aws', 'cloudtrail', 'cloudtrail_s3_dataevents_write_enabled', 'CloudTrail trail records all S3 object-level API operations for all buckets', '**CloudTrail trails** include **S3 object-level data events** for **write (or all) operations** across **all current and future buckets**, via classic or advanced selectors. This records actions like `PutObject`, `DeleteObject`, and multipart uploads at the object level.', 2, NULL, 'Enable **CloudTrail S3 data events** for object-level **write** (and *optionally* read) across all buckets on a multi-Region trail. Apply **least privilege** to log storage, set **lifecycle** retention, and integrate alerts. Use **advanced selectors** to target sensitive buckets/operations for cost control and **defense in depth**.', 'https://hub.prowler.com/check/cloudtrail_s3_dataevents_write_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(858, 'aws', 'cloudwatch', 'cloudwatch_changes_to_network_acls_alarm_configured', 'CloudWatch log metric filter and alarm exist for Network ACL (NACL) change events', 'CloudTrail records for **Network ACL changes** are matched by a CloudWatch Logs metric filter with an associated alarm for events like `CreateNetworkAcl`, `CreateNetworkAclEntry`, `DeleteNetworkAcl`, `DeleteNetworkAclEntry`, `ReplaceNetworkAclEntry`, and `ReplaceNetworkAclAssociation`.', 3, NULL, 'Implement a CloudWatch Logs metric filter and alarm for NACL change events from CloudTrail and route alerts to responders. Enforce **least privilege** on NACL management, require **change control**, and use **defense in depth** with configuration monitoring and flow logs to validate and monitor network posture.', 'https://hub.prowler.com/check/cloudwatch_changes_to_network_acls_alarm_configured', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(859, 'aws', 'cloudwatch', 'cloudwatch_changes_to_network_gateways_alarm_configured', 'CloudWatch Logs metric filter and alarm exist for changes to network gateways', 'CloudWatch log metric filters and alarms for **network gateway changes** are identified by matching CloudTrail events such as `CreateCustomerGateway`, `DeleteCustomerGateway`, `AttachInternetGateway`, `CreateInternetGateway`, `DeleteInternetGateway`, and `DetachInternetGateway` in log groups that receive trail logs.', 3, NULL, 'Send CloudTrail to CloudWatch Logs and create a metric filter for the listed gateway events with an alarm that notifies responders. Enforce **least privilege** for gateway modifications, require change approvals, and route alerts to monitored channels as part of **defense in depth**.', 'https://hub.prowler.com/check/cloudwatch_changes_to_network_gateways_alarm_configured', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(860, 'aws', 'cloudwatch', 'cloudwatch_changes_to_network_route_tables_alarm_configured', 'Account monitors VPC route table changes with a CloudWatch Logs metric filter and alarm', '**VPC route table changes** are captured from **CloudTrail logs** by a **CloudWatch Logs metric filter** with an associated **alarm** for events like `CreateRoute`, `CreateRouteTable`, `ReplaceRoute`, `ReplaceRouteTableAssociation`, `DeleteRoute`, `DeleteRouteTable`, and `DisassociateRouteTable`.', 3, NULL, 'Implement a **CloudWatch Logs metric filter and alarm** on CloudTrail for these route table events and notify responders. Enforce **least privilege** for route modifications, require **change control**, and apply **defense in depth** with VPC Flow Logs and guardrails to prevent and quickly contain unsafe routing changes.', 'https://hub.prowler.com/check/cloudwatch_changes_to_network_route_tables_alarm_configured', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(861, 'aws', 'cloudwatch', 'cloudwatch_changes_to_vpcs_alarm_configured', 'AWS account has a CloudWatch Logs metric filter and alarm for VPC changes', '**CloudTrail events** for **VPC configuration changes** are captured in CloudWatch Logs with a metric filter and an associated alarm. The filter targets actions like `CreateVpc`, `DeleteVpc`, `ModifyVpcAttribute`, and VPC peering operations to surface when network topology is altered.', 3, NULL, 'Create a CloudWatch Logs metric filter and alarm on CloudTrail for critical **VPC change events**, and notify responders. Apply **least privilege** to network changes, require change approvals, and use **defense in depth** (segmentation, route controls) to prevent and contain unauthorized modifications.', 'https://hub.prowler.com/check/cloudwatch_changes_to_vpcs_alarm_configured', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(862, 'aws', 'cloudwatch', 'cloudwatch_log_group_kms_encryption_enabled', 'CloudWatch log group is encrypted with an AWS KMS key', '**CloudWatch log groups** are assessed for **at-rest encryption** by checking if an **AWS KMS key** is associated with the log group via `kmsKeyId`.', 3, NULL, 'Associate each log group with a **customer-managed KMS key** via `kmsKeyId`.\n- Enforce **least privilege** in key and IAM policies, granting `kms:Decrypt` only to required principals\n- Enable rotation and monitor key usage\n- Separate keys by app/tenant to support **defense in depth** and rapid revocation', 'https://hub.prowler.com/check/cloudwatch_log_group_kms_encryption_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(870, 'aws', 'cloudwatch', 'cloudwatch_log_group_retention_policy_specific_days_enabled', 'CloudWatch log group has a retention policy of at least the configured minimum days or never expires', '**CloudWatch Log Groups** are assessed for a retention period at or above the configured threshold (e.g., `365` days) or for being set to **never expire**. Log groups with shorter retention are identified.', 3, NULL, 'Define a minimum retention baseline (e.g., `>=365` days) aligned to legal and investigative needs. Apply it consistently with documented exceptions. Automate enforcement, monitor changes, and restrict who can modify retention under **least privilege** and **defense in depth**.', 'https://hub.prowler.com/check/cloudwatch_log_group_retention_policy_specific_days_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(874, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_and_alarm_for_aws_config_configuration_changes_enabled', 'CloudWatch Logs metric filter and alarm exist for AWS Config configuration changes', 'CloudTrail logs in **CloudWatch Logs** are inspected for a metric filter and alarm that track **AWS Config configuration changes**, specifically `StopConfigurationRecorder`, `DeleteDeliveryChannel`, `PutDeliveryChannel`, and `PutConfigurationRecorder` events from `config.amazonaws.com`.', 3, NULL, 'Create a **CloudWatch Logs metric filter and alarm** for `config.amazonaws.com` events (`StopConfigurationRecorder`, `DeleteDeliveryChannel`, `PutDeliveryChannel`, `PutConfigurationRecorder`). Route CloudTrail to Logs, notify responders, and enforce **least privilege** and **separation of duties** on Config changes to prevent abuse.', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_and_alarm_for_aws_config_configuration_changes_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(875, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_and_alarm_for_cloudtrail_configuration_changes_enabled', 'CloudWatch Logs metric filter and alarm exist for CloudTrail configuration changes', '**CloudTrail logs** include a **metric filter** for trail configuration events (`CreateTrail`, `UpdateTrail`, `DeleteTrail`, `StartLogging`, `StopLogging`) with an associated **CloudWatch alarm** to alert on matches.\n\nEvaluates the presence of this filter-and-alarm monitoring.', 3, NULL, 'Implement a **metric filter** for trail configuration events and a linked **alarm** that notifies response channels.\n\nApply **least privilege** and **separation of duties** for trail changes, add **defense in depth** with centralized logging and validation, and regularly test that alerts fire.', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_and_alarm_for_cloudtrail_configuration_changes_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(876, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_authentication_failures', 'Account has a CloudWatch Logs metric filter and alarm for AWS Management Console authentication failures', 'CloudWatch Logs metric filter and alarm for **AWS Management Console authentication failures**, sourced from CloudTrail (`eventName=ConsoleLogin`, `errorMessage=\"Failed authentication\"`).\n\nIdentifies whether these failures are converted into a metric and actively monitored by an alarm.', 3, NULL, 'Implement a log metric filter for `ConsoleLogin` failures and attach a **CloudWatch alarm** with actionable notifications. Tune thresholds to reduce noise and route alerts to incident response.\n\nApply **least privilege** and enforce **MFA** to limit impact, and correlate alerts with source IP and user context.', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_authentication_failures', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(877, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_aws_organizations_changes', 'CloudWatch Logs metric filter and alarm exist for AWS Organizations changes', '**CloudWatch Logs** metric filters and alarms monitor **AWS Organizations** change events recorded by CloudTrail, including actions like `CreateAccount`, `AttachPolicy`, `MoveAccount`, and `UpdateOrganizationalUnit`.\n\nThe evaluation looks for a filter on the trail log group matching `organizations.amazonaws.com` events and an alarm linked to that metric.', 3, NULL, 'Send CloudTrail events to **CloudWatch Logs**, add a metric filter for `organizations.amazonaws.com` change events, and attach an alarm that notifies responders. Enforce **least privilege** and **separation of duties** for org admins, require MFA and approvals, and regularly test alerts to ensure timely detection and response.', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_aws_organizations_changes', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(878, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_disable_or_scheduled_deletion_of_kms_cmk', 'Account has a CloudWatch log metric filter and alarm for disabling or scheduled deletion of customer-managed KMS keys', 'CloudTrail events delivered to CloudWatch are evaluated for a **metric filter and alarm** that monitor **KMS CMK state changes**, specifically `DisableKey` and `ScheduleKeyDeletion` from `kms.amazonaws.com`.', 3, NULL, 'Establish **CloudWatch metric filters and alarms** for `DisableKey` and `ScheduleKeyDeletion` CloudTrail events to enable rapid response.\n- Apply **least privilege** to KMS administration\n- Enforce **change control** and separation of duties\n- Use deletion waiting periods and monitor all regions', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_disable_or_scheduled_deletion_of_kms_cmk', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(879, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_for_s3_bucket_policy_changes', 'CloudWatch log metric filter and alarm exist for S3 bucket policy changes', '**CloudTrail** logs are assessed for a **CloudWatch metric filter** matching S3 bucket configuration changes (ACL, policy, CORS, lifecycle, replication; e.g., `PutBucketPolicy`, `DeleteBucketPolicy`) and for an associated **CloudWatch alarm**.', 3, NULL, 'Establish and maintain **metric filters** and **alarms** for S3 bucket policy, ACL, CORS, lifecycle, and replication changes. Route alerts to monitored channels and integrate with SIEM. Enforce **least privilege**, require change reviews, and use **defense in depth** to prevent and quickly detect unsafe bucket policy changes.', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_for_s3_bucket_policy_changes', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(880, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_policy_changes', 'CloudWatch Logs metric filter and alarm exist for IAM policy changes', 'CloudWatch uses a metric filter and alarm to track **IAM policy changes** recorded by CloudTrail (e.g., `CreatePolicy`, `DeletePolicy`, version changes, inline policy edits, policy attach/detach). This finding reflects whether that filter and an associated alarm are present on the trail\'s log group.', 3, NULL, 'Create a metric filter for IAM policy create/update/delete and attach/detach events with an **alarm** to notify responders.\n- Enforce **least privilege** and separation of duties for policy changes\n- Require approvals and central logging across Regions/accounts\n- Integrate alerts with incident response', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_policy_changes', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(881, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_root_usage', 'Account has a CloudWatch Logs metric filter and alarm for root account usage', '**CloudTrail** logs in CloudWatch include a metric filter for **root account activity** (`{ $.userIdentity.type = \"Root\" && $.userIdentity.invokedBy NOT EXISTS && $.eventType != \"AwsServiceEvent\" }`) and a linked CloudWatch alarm that triggers when the filter matches.', 3, NULL, 'Enable real-time alerts for **root activity** using a log metric filter and a high-priority alarm with notifications.\n\nReduce exposure: enforce **least privilege**, keep root for *break-glass* with MFA, disable root access keys, and route alerts into incident response for **defense in depth**.', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_root_usage', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(882, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_security_group_changes', 'CloudWatch Logs metric filter and alarm exist for security group changes', '**CloudTrail** events for **security group configuration changes** are monitored using a **CloudWatch Logs metric filter** with an associated **alarm**. The filter targets actions like `AuthorizeSecurityGroupIngress/Egress`, `RevokeSecurityGroupIngress/Egress`, `CreateSecurityGroup`, and `DeleteSecurityGroup` to surface any security group modifications.', 3, NULL, 'Establish real-time alerts for **security group modifications** by sending CloudTrail to CloudWatch, creating metric filters and alarms, and notifying responders.\n- Enforce **least privilege** on SG changes\n- Use change management and tagging\n- Centralize logs, test alarms, and maintain runbooks\n- Layer with NACLs and WAF for **defense in depth**', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_security_group_changes', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(883, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_sign_in_without_mfa', 'CloudWatch log metric filter and alarm exist for Management Console sign-in without MFA', '**CloudTrail logs** in CloudWatch are assessed for a metric filter and alarm that detect console logins where `$.eventName = ConsoleLogin` and `$.additionalEventData.MFAUsed != \\\"Yes\\\"`.\n\nThis reflects whether alerting exists for sign-ins that occur without **MFA**.', 3, NULL, 'Enforce **MFA** for all console-capable identities and maintain alerts for `ConsoleLogin` with `MFAUsed != \\\"Yes\\\"`.\n\nApply **least privilege**, route alarms to monitored channels, and tune for SSO to reduce noise. Test alarms regularly and review coverage as part of **defense in depth**.', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_sign_in_without_mfa', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(884, 'aws', 'cloudwatch', 'cloudwatch_log_metric_filter_unauthorized_api_calls', 'CloudWatch Logs metric filter and alarm exist for unauthorized API calls', '**CloudWatch Logs** for CloudTrail include a metric filter that matches unauthorized API errors (`$.errorCode=\"*UnauthorizedOperation\"` or `$.errorCode=\"AccessDenied*\"`) and a linked alarm that triggers when events match the filter.', 3, NULL, 'Enable real-time **alerting** by adding a CloudWatch Logs metric filter for unauthorized errors (`*UnauthorizedOperation`, `AccessDenied*`) and associating it with an alarm that notifies responders.\n- Enforce **least privilege** to reduce noise\n- Integrate with IR tooling for **defense in depth**', 'https://hub.prowler.com/check/cloudwatch_log_metric_filter_unauthorized_api_calls', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(885, 'aws', 'config', 'config_delegated_admin_and_org_aggregator_all_regions', 'AWS Config has a delegated administrator and an organization aggregator covering all AWS regions', '**AWS Config** has a delegated administrator registered via AWS Organizations and at least one Configuration Aggregator with an OrganizationAggregationSource that covers all AWS regions, ensuring centralized org-wide configuration visibility.', 4, NULL, 'Register a **delegated administrator** for AWS Config via AWS Organizations and create at least one **Configuration Aggregator** with an OrganizationAggregationSource that covers **all AWS regions**. This centralizes configuration data across the organization for unified compliance and audit reporting.', 'https://hub.prowler.com/check/config_delegated_admin_and_org_aggregator_all_regions', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(886, 'aws', 'config', 'config_recorder_all_regions_enabled', 'AWS Config recorder is enabled and not in failure state or disabled', '**AWS accounts** have **AWS Config recorders** active and healthy in each Region. It identifies Regions with no recorder, a disabled recorder, or a recorder in a failure state.', 3, NULL, 'Enable **AWS Config** in every Region with continuous recording and maintain healthy recorder status.', 'https://hub.prowler.com/check/config_recorder_all_regions_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(901, 'aws', 'dlm', 'dlm_ebs_snapshot_lifecycle_policy_exists', 'Region with EBS snapshots has at least one EBS snapshot lifecycle policy defined', '**EBS snapshots** are expected to be governed by **Data Lifecycle Manager (DLM) policies** in each Region where snapshots exist.\n\nThe evaluation looks for lifecycle policies that automate snapshot creation, retention, and cleanup for those snapshots.', 3, NULL, 'Implement **DLM lifecycle policies** for all volumes that require backup.\n\n- Schedule creations to meet RPO/RTO\n- Define retention to prevent sprawl and enforce least data exposure\n- Use **least privilege** roles and separation of duties\n- Copy snapshots to another Region/account for **defense in depth**\n- Monitor policy health and coverage with tags', 'https://hub.prowler.com/check/dlm_ebs_snapshot_lifecycle_policy_exists', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(902, 'aws', 'drs', 'drs_job_exist', 'Region has AWS Elastic Disaster Recovery (DRS) enabled with at least one recovery job', '**AWS Elastic Disaster Recovery** is assessed per Region to verify the service is **initialized** and that at least one **recovery or drill job** exists, demonstrating that failover has been exercised.', 3, NULL, 'Enable DRS in required Regions and protect critical workloads. Define RTO/RPO and run **regular recovery drills** to validate launch settings and dependencies. Apply **least privilege**, monitor replication health, and document failover procedures to ensure consistent, repeatable recovery.', 'https://hub.prowler.com/check/drs_job_exist', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(904, 'aws', 'ec2', 'ec2_networkacl_allow_ingress_any_port', 'Network ACL does not allow ingress from 0.0.0.0/0 to any port', '**VPC network ACLs** with **inbound entries** that permit traffic from `0.0.0.0/0` to any port (any protocol) are identified at the subnet boundary.', 4, NULL, 'Adopt a **deny-by-default** NACL posture: block `0.0.0.0/0` and allow only required ports from trusted CIDRs. Apply **least privilege** using security groups for fine-grained access, with NACLs as coarse stateless filters. Review and prune rules regularly, and employ **defense in depth** with monitoring and alerting.', 'https://hub.prowler.com/check/ec2_networkacl_allow_ingress_any_port', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(905, 'aws', 'ec2', 'ec2_networkacl_allow_ingress_tcp_port_22', 'Network ACL does not allow ingress from the Internet to TCP port 22 (SSH)', '**VPC network ACLs** are evaluated for inbound rules that permit `0.0.0.0/0` to access **SSH** on `TCP 22` at the subnet boundary.', 3, NULL, 'Apply **least privilege** at the subnet layer:\n- Do not allow `0.0.0.0/0` to `TCP 22`\n- Restrict SSH to trusted sources, or avoid direct SSH via **Session Manager** or a bastion behind **VPN**\n\nPair tight **security groups** with periodic rule reviews and change control to maintain **defense in depth**.', 'https://hub.prowler.com/check/ec2_networkacl_allow_ingress_tcp_port_22', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(906, 'aws', 'ec2', 'ec2_networkacl_allow_ingress_tcp_port_3389', 'Network ACL does not allow ingress from the Internet to TCP port 3389 (RDP)', '**VPC network ACLs** with inbound rules allowing **RDP** on `TCP 3389` from `0.0.0.0/0` are identified.\n\nAssessment focuses on subnet-level ACL entries that permit this traffic.', 3, NULL, 'Enforce **least privilege**: do not allow `TCP 3389` from `0.0.0.0/0` in network ACLs.\n\n- Restrict RDP to specific admin IP ranges\n- Prefer **bastion hosts** or **Session Manager** over direct RDP\n- Use private subnets and layer controls for **defense in depth**', 'https://hub.prowler.com/check/ec2_networkacl_allow_ingress_tcp_port_3389', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(907, 'aws', 'ec2', 'ec2_securitygroup_not_used', 'Non-default EC2 security group is in use', 'EC2 security groups, except `default`, are assessed for **unused** status: zero attached network interfaces, no AWS Lambda associations, and no references from other security groups.', 2, NULL, 'Apply **least privilege** and strong lifecycle management: delete or quarantine **unused security groups**, enforce ownership tags and retention policies, review regularly, and manage changes via IaC with approvals. Restrict who can attach groups and use guardrails to prevent reuse of stale or permissive groups.', 'https://hub.prowler.com/check/ec2_securitygroup_not_used', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(908, 'aws', 'guardduty', 'guardduty_delegated_admin_enabled_all_regions', 'GuardDuty has delegated admin configured and is enabled in all regions with organization auto-enable', '**Amazon GuardDuty** has a delegated administrator configured at the organization level, detectors are enabled in all opted-in regions, and organization auto-enable is active for new member accounts.', 4, NULL, 'Configure a **delegated administrator** for GuardDuty via AWS Organizations. Enable GuardDuty detectors in **all opted-in regions** and configure **auto-enable** to automatically enroll new member accounts. This ensures consistent threat detection coverage across the entire organization.', 'https://hub.prowler.com/check/guardduty_delegated_admin_enabled_all_regions', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(910, 'aws', 'guardduty', 'guardduty_is_enabled', 'GuardDuty detector is enabled and not suspended', '**Amazon GuardDuty** detector existence and health are evaluated per Region. It identifies where GuardDuty isn\'t enabled for the account, where a detector has no status, or where a detector is configured but `suspended`.', 4, NULL, 'Enable and keep **GuardDuty** active in all supported Regions and accounts under a delegated admin. Turn on relevant protection plans and auto-enroll new accounts. Avoid `suspended` detectors, enforce **least privilege** for admins, and integrate findings into response for **defense in depth**.', 'https://hub.prowler.com/check/guardduty_is_enabled', '2026-08-02 18:28:59', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:28:59', 1),
(912, 'aws', 'iam', 'iam_aws_attached_policy_no_administrative_privileges', 'Attached AWS-managed IAM policy does not allow \'*:*\' administrative privileges', '**IAM AWS-managed policies** attached to identities are inspected for statements that allow `Action:\'*\'` on `Resource:\'*\'`-i.e., full administrative `*:*` permissions', 5, NULL, 'Apply **least privilege**: avoid attaching AWS-managed policies that grant `*:*`.\n- Use **customer-managed, scoped policies** per role\n- Enforce **separation of duties** and **permissions boundaries**\n- Prefer **temporary, time-bound elevation** for emergencies with MFA\n- Regularly review access and use conditions to constrain context', 'https://hub.prowler.com/check/iam_aws_attached_policy_no_administrative_privileges', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(913, 'aws', 'iam', 'iam_inline_policy_allows_privilege_escalation', 'IAM inline policy does not allow privilege escalation', '**IAM inline policies** are evaluated for permission combinations that enable **privilege escalation**, such as `sts:AssumeRole`, `iam:PassRole`, attaching/editing policies, or broad wildcards. The result highlights inline policies that allow a principal to obtain higher effective access.', 4, NULL, 'Apply **least privilege** and remove escalation paths:\n- Avoid wildcards and sensitive actions like `sts:AssumeRole`, `iam:PassRole`, or policy modification without tight scope\n- Restrict by resource and `Condition`\n- Prefer managed, versioned policies; use permissions boundaries/SCPs\n- Require reviews and MFA for admins', 'https://hub.prowler.com/check/iam_inline_policy_allows_privilege_escalation', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(917, 'aws', 'iam', 'iam_inline_policy_no_administrative_privileges', 'Inline IAM policy does not allow \'*:*\' administrative privileges', '**IAM inline policies** on identities are evaluated for statements allowing `Action:\"*\"` on `Resource:\"*\"`, which indicates **unrestricted administrative access**.', 5, NULL, 'Remove `Action:\"*\"` with `Resource:\"*\"` from inline policies. Apply **least privilege** with granular actions scoped to specific resources and conditions. Prefer versioned customer-managed policies over broad inline ones, enforce **separation of duties**, and use **permissions boundaries** or guardrails to prevent accidental admin grants.', 'https://hub.prowler.com/check/iam_inline_policy_no_administrative_privileges', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(918, 'aws', 'iam', 'iam_inline_policy_no_full_access_to_cloudtrail', 'Inline IAM policy does not allow \'cloudtrail:*\' privileges', '**IAM inline policies** are evaluated for statements that grant **full CloudTrail permissions** (`cloudtrail:*`) to all resources.\n\nThe finding flags identity policies that provide unrestricted control over CloudTrail operations.', 4, NULL, 'Enforce **least privilege** and **separation of duties**: avoid `cloudtrail:*`; grant only specific actions needed (prefer read-only where possible). Add guardrails or boundaries to block destructive actions. Use managed, centrally governed policies and periodically right-size permissions based on usage.', 'https://hub.prowler.com/check/iam_inline_policy_no_full_access_to_cloudtrail', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(919, 'aws', 'iam', 'iam_inline_policy_no_full_access_to_kms', 'Inline IAM policy does not allow kms:* privileges', '**IAM inline policies** are analyzed to identify statements that grant **unrestricted AWS KMS access** via the wildcard action `kms:*`.', 3, NULL, 'Replace `kms:*` with **least-privilege**, action-scoped permissions limited to required operations and specific key ARNs. Enforce **separation of duties** for key admins vs users. Prefer **managed policies** over inline and apply guardrails (permissions boundaries/SCPs). Add conditions to constrain service, region, and encryption context.', 'https://hub.prowler.com/check/iam_inline_policy_no_full_access_to_kms', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(920, 'aws', 'iam', 'iam_role_access_not_stale_to_bedrock', 'Regular Bedrock access ensures IAM roles retain only actively used permissions', 'IAM roles granted **Bedrock** permissions are evaluated for recent service usage.\n\nRoles whose last Bedrock access exceeds the configured threshold (default **60 days**) or that have **never** accessed Bedrock are flagged, indicating stale permissions that should be reviewed.', 3, NULL, 'Apply the **principle of least privilege** by regularly reviewing IAM Access Advisor data and revoking Bedrock permissions that are no longer actively used.\n\nEstablish a periodic access review process and automate alerts for stale permissions to maintain a minimal attack surface.', 'https://hub.prowler.com/check/iam_role_access_not_stale_to_bedrock', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(932, 'aws', 'iam', 'iam_role_administratoraccess_policy', 'IAM role does not have AdministratorAccess policy attached', '**IAM roles** (excluding service roles) are evaluated for attachment of the AWS-managed `AdministratorAccess` policy.\n\nAttachment indicates the role holds unrestricted permissions across services and resources.', 4, NULL, 'Apply **least privilege**: avoid attaching `AdministratorAccess` to roles. Grant only task-scoped permissions with custom policies and enforce **separation of duties**.\n\nUse **permissions boundaries**, **SCPs**, and policy conditions to constrain power. Require MFA for break-glass admins, time-bound elevation with approval, and refine access using **Access Analyzer**.', 'https://hub.prowler.com/check/iam_role_administratoraccess_policy', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(938, 'aws', 'iam', 'iam_role_cross_account_readonlyaccess_policy', 'IAM role does not grant ReadOnlyAccess to external AWS accounts', '**IAM roles** are assessed for the AWS-managed **ReadOnlyAccess** policy combined with a trust policy that allows **external AWS principals** or `*`. This identifies roles that expose broad read permissions to other accounts.', 4, NULL, 'Avoid attaching `ReadOnlyAccess` to roles trusted by other accounts. Apply **least privilege** with custom, tightly scoped policies. Restrict trust to explicit principals, avoid `*`, and use conditions like `aws:PrincipalOrgID` and `sts:ExternalId` for **defense in depth**.', 'https://hub.prowler.com/check/iam_role_cross_account_readonlyaccess_policy', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(939, 'aws', 'iam', 'iam_role_cross_service_confused_deputy_prevention', 'IAM service role prevents cross-service confused deputy attack', '**IAM service role** trust policies restrict **AWS service principals** to expected sources using global condition keys like `aws:SourceArn` or `aws:SourceAccount`, avoiding overly broad `sts:AssumeRole` trust relationships.', 4, NULL, 'Constrain service-role trust to expected callers using `aws:SourceArn`/`aws:SourceAccount` to bind service principals to specific resources or accounts. If unsupported, apply equivalent limits in resource-based policies or org-level controls. Apply **least privilege** and review trust relationships regularly.', 'https://hub.prowler.com/check/iam_role_cross_service_confused_deputy_prevention', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(948, 'aws', 'iam', 'iam_root_credentials_management_enabled', 'AWS Organization has centralized root credentials management enabled', '**AWS Organizations** uses **centralized root credentials management** to control root user credentials across member accounts.\n\nThis finding evaluates whether the organization has enabled the `RootCredentialsManagement` feature to centrally govern presence and recovery of root passwords, access keys, signing certificates, and MFA.', 4, NULL, 'Enable centralized root access with **root credentials management** and assign a **delegated administrator**.\n\nApply **least privilege** and **separation of duties** by deleting long-term root credentials in members, limiting privileged tasks to short-lived sessions, enforcing **MFA**, and auditing root-related activity for **defense in depth**.', 'https://hub.prowler.com/check/iam_root_credentials_management_enabled', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(949, 'aws', 'iam', 'iam_root_hardware_mfa_enabled', 'Root account has a hardware MFA device enabled', '**AWS root user** credentials are assessed for **MFA status** and device type. The check detects whether MFA is absent or implemented with a **virtual device** instead of **hardware MFA** on the root user, and notes when centralized root credential management is in effect.', 5, NULL, 'Require a **hardware MFA token** for the root user and remove any virtual MFA. Apply **least privilege**: avoid using root, disable access keys, and eliminate long-term credentials. In organizations, **centralize root management**. Keep a controlled break-glass process with strict recovery checks and continuous monitoring.', 'https://hub.prowler.com/check/iam_root_hardware_mfa_enabled', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(950, 'aws', 'iam', 'iam_support_role_created', 'At least one IAM role has the AWSSupportAccess managed policy attached', 'Presence of an **IAM role** that has the AWS managed `AWSSupportAccess` policy attached, designating a support role for interacting with **AWS Support Center** and related tooling.', 2, NULL, 'Create a dedicated IAM role for AWS Support with `AWSSupportAccess` and:\n- Restrict who can assume it; require MFA and time-bound access\n- Enforce **least privilege** and **separation of duties**\n- Monitor usage via audit logs and review assignments regularly', 'https://hub.prowler.com/check/iam_support_role_created', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(951, 'aws', 'inspector2', 'inspector2_is_enabled', 'Inspector2 is enabled for Amazon EC2 instances, ECR container images, Lambda functions, and Lambda code', '**Amazon Inspector 2** activation and coverage across regions, verifying that scanning is active for **EC2**, **ECR**, **Lambda functions**, and **Lambda code** where applicable.\n\nIt flags missing account activation or gaps in any scan type.', 3, NULL, 'Enable **Amazon Inspector 2** across all regions and activate scans for **EC2**, **ECR**, **Lambda**, and **Lambda code**.\n\nApply **defense in depth**: auto-enable coverage for new workloads, integrate findings with patching and CI/CD gates, enforce remediation SLAs, and grant only **least privilege** to process and act on findings.', 'https://hub.prowler.com/check/inspector2_is_enabled', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(953, 'aws', 'kms', 'kms_cmk_not_deleted_unintentionally', 'AWS KMS customer managed key is not scheduled for deletion', '**Customer-managed KMS keys** are evaluated for the `PendingDeletion` state, indicating a scheduled deletion during the mandatory waiting period.', 5, NULL, 'Prevent unintended deletion:\n- Enforce **least privilege** and **separation of duties** for key admins\n- Require change approvals and alerts on deletion events\n- Prefer **disabling** unused keys over deleting\n- Set sufficient waiting periods and review keys in `PendingDeletion` to verify authorization', 'https://hub.prowler.com/check/kms_cmk_not_deleted_unintentionally', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(954, 'aws', 'macie', 'macie_is_enabled', 'Amazon Macie is enabled', '**Amazon Macie** status is assessed per region with **S3** presence to determine if sensitive data discovery is operational. The outcome reflects whether Macie is active or in a `PAUSED`/not enabled state for the account and region.', 3, NULL, 'Enable and maintain **Amazon Macie** in all regions hosting **S3** data. Use continuous sensitive data discovery, apply custom classifications for your data types, and route findings to monitoring. Enforce least privilege for Macie access and strengthen defense in depth with restrictive bucket policies and access controls.', 'https://hub.prowler.com/check/macie_is_enabled', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(955, 'aws', 's3', 's3_bucket_cross_region_replication', 'S3 bucket has cross-region replication configured to a bucket in a different region', '**Amazon S3 buckets** use **cross-Region replication** with `versioning` and an enabled rule that targets a destination bucket in a different AWS Region.\n\nBuckets with same-Region targets, missing destinations, or disabled `versioning` don\'t meet this replication posture.', 2, NULL, 'Enable **CRR** to a different Region with `versioning` and least-privilege roles.\n\n- Replicate needed prefixes and metadata\n- Consider `S3 Replication Time Control` for tighter RPO\n- Protect deletes via `delete marker` strategy and Object Lock\n- Monitor replication metrics and test DR regularly\n\nAlign with **defense in depth** and availability by design.', 'https://hub.prowler.com/check/s3_bucket_cross_region_replication', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1);
INSERT INTO `security_rules` (`id`, `provider`, `service`, `check_id`, `title`, `description`, `severidad_id`, `condition_logic`, `remediation`, `reference`, `actualizacion`, `display_name`, `creado_por_ia`, `origen`, `validado_por`, `validado_at`, `creacion`, `estado_id`) VALUES
(957, 'aws', 's3', 's3_bucket_event_notifications_enabled', 'S3 bucket has event notifications enabled', '**Amazon S3 buckets** define a **notification configuration** that publishes bucket events (for example `s3:ObjectCreated:*`, `s3:ObjectRemoved:*`) to a destination. The evaluation identifies buckets that lack any notification setup.', 2, NULL, 'Enable **S3 event notifications** for relevant events (e.g., `s3:ObjectCreated:*`, `s3:ObjectRemoved:*`) and route to controlled destinations (SNS, SQS, Lambda, EventBridge).\n\nUse prefix/suffix filters, avoid recursive triggers, and enforce **least privilege** on targets. Pair with object-level logging for **defense in depth**.', 'https://hub.prowler.com/check/s3_bucket_event_notifications_enabled', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(959, 'aws', 's3', 's3_bucket_kms_encryption', 'S3 bucket has server-side encryption with AWS KMS', '**Amazon S3 buckets** use server-side encryption with **AWS KMS** keys, including dual-layer `aws:kms:dsse`. The evaluation identifies buckets whose default encryption is `aws:kms` or `aws:kms:dsse` rather than SSE-S3.', 3, NULL, 'Enable default **SSE-KMS** (or **DSSE-KMS** for highly sensitive data). Use a customer-managed key, enforce **least privilege** and separation of duties for key usage, and require KMS encryption via bucket policy (specify `aws:kms` and a designated key). Monitor key activity in **CloudTrail** and consider **S3 Bucket Keys** to control cost.', 'https://hub.prowler.com/check/s3_bucket_kms_encryption', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(961, 'aws', 's3', 's3_bucket_lifecycle_enabled', 'S3 bucket has a lifecycle configuration enabled', '**Amazon S3 buckets** use **Lifecycle configurations** with at least one rule `Status: Enabled` to automate object `Transitions` and `Expiration` based on age, prefix, or tags', 2, NULL, 'Define **Lifecycle policies** by data classification: set `Expiration` to enforce retention, use `Transitions` to lower-cost classes, and enable `AbortIncompleteMultipartUpload`. For critical logs, keep versioning and, *if required*, **Object Lock**. Limit who can change lifecycle using least privilege and separation of duties.', 'https://hub.prowler.com/check/s3_bucket_lifecycle_enabled', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(963, 'aws', 's3', 's3_bucket_no_mfa_delete', 'S3 bucket has MFA Delete enabled', '**Amazon S3 buckets** are assessed for **MFA Delete** status. MFA Delete requires a second factor to permanently delete object versions or change `Versioning` configuration. The finding highlights buckets where this protection is not enabled.', 3, NULL, 'Enable **MFA Delete** on sensitive, versioned buckets so permanent deletions and `Versioning` changes require a second factor. Apply **least privilege** to restrict version purge actions, enforce **change control**, and combine with **Object Lock** or immutable backups for defense in depth.', 'https://hub.prowler.com/check/s3_bucket_no_mfa_delete', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(965, 'aws', 's3', 's3_bucket_object_lock', 'S3 bucket has Object Lock enabled', '**Amazon S3 buckets** have **Object Lock** enabled at the bucket level, applying WORM controls to object versions', 2, NULL, 'Enable **Object Lock** for critical data and set appropriate default retention in `GOVERNANCE` or `COMPLIANCE` mode.\n\nApply **immutability** and **least privilege** by restricting permissions that bypass retention, and use legal holds when you need indefinite protection for investigations or regulatory requirements.', 'https://hub.prowler.com/check/s3_bucket_object_lock', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(967, 'aws', 's3', 's3_bucket_object_versioning', 'S3 bucket has object versioning enabled', '**Amazon S3 buckets** are evaluated for **object versioning** being `Enabled`, which maintains multiple versions of the same object key for historical state retention', 3, NULL, 'Enable **S3 versioning** for buckets holding important or shared data.\n- Enforce **least privilege** to limit delete/overwrite\n- Use **Object Lock** and/or **MFA Delete** for stronger protection\n- Apply **lifecycle rules** to manage noncurrent versions and costs\n- Layer with backups/replication for **defense in depth**', 'https://hub.prowler.com/check/s3_bucket_object_versioning', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(968, 'aws', 's3', 's3_bucket_secure_transport_policy', 'S3 bucket policy denies requests over insecure transport', '**Amazon S3 buckets** are evaluated for a bucket policy that enforces **secure transport** by denying requests when `aws:SecureTransport` is `false`.\n\nBuckets without this explicit denial, or without a policy, are treated as allowing access over insecure transport.', 3, NULL, 'Enforce **HTTPS-only** access with a bucket policy that denies requests when `aws:SecureTransport=false`.\n\nPrefer **private access** (VPC endpoints or CloudFront with TLS), avoid S3 website endpoints, apply **least privilege**, use short-lived HTTPS **pre-signed URLs**, and monitor logs for insecure access attempts.', 'https://hub.prowler.com/check/s3_bucket_secure_transport_policy', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(970, 'aws', 's3', 's3_bucket_server_access_logging_enabled', 'S3 bucket has server access logging enabled', '**Amazon S3 buckets** are evaluated for **server access logging** configured to record access requests and deliver logs to a designated destination bucket.', 3, NULL, 'Enable **server access logging** and send logs to a dedicated log bucket with least privilege, retention, and monitoring. Complement with **CloudTrail data events** for object-level visibility. Apply **defense in depth** by centralizing logs and protecting them from tampering.', 'https://hub.prowler.com/check/s3_bucket_server_access_logging_enabled', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(972, 'aws', 'sagemaker', 'sagemaker_clarify_exists', 'Amazon SageMaker Clarify processing jobs exist in the region', '**SageMaker Clarify** provides bias detection and model explainability for ML workloads.\n\nThis check verifies that at least one SageMaker processing job using the AWS-managed Clarify container image exists in each successfully scanned region. The absence of Clarify jobs indicates that responsible-AI controls such as bias detection and explainability are not in place.', 2, NULL, 'Create SageMaker Clarify processing jobs to evaluate models for bias and explainability before deployment. Integrate Clarify into your ML pipeline to ensure responsible AI practices.', 'https://hub.prowler.com/check/sagemaker_clarify_exists', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(974, 'aws', 'sagemaker', 'sagemaker_models_monitor_enabled', 'Amazon SageMaker has a monitoring schedule scheduled', '**SageMaker Models Monitor** detects data drift, model quality issues, and bias drift in production.', 2, NULL, 'Enable **Amazon SageMaker Model Monitor** and keep at least one **monitoring schedule** in the `Scheduled` state so data quality, model quality, and bias drift are continuously evaluated against a baseline.', 'https://hub.prowler.com/check/sagemaker_models_monitor_enabled', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(991, 'aws', 'sagemaker', 'sagemaker_models_registry_in_use', 'Amazon SageMaker Model Registry should have at least one approved model package', '**SageMaker Model Registry** is evaluated to verify that at least one Model Package Group exists and contains at least one model package with **ModelApprovalStatus = Approved**. This confirms that the ML governance workflow (register → review → approve → deploy) is actively in use.', 2, NULL, 'Register all production models in the **SageMaker Model Registry** and enforce an approval workflow before deployment. Ensure at least one model package per group reaches **Approved** status. Use **IAM policies** to restrict who can approve model packages and integrate with **CI/CD pipelines** to automate registration.', 'https://hub.prowler.com/check/sagemaker_models_registry_in_use', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(993, 'aws', 'securityhub', 'securityhub_delegated_admin_enabled_all_regions', 'Security Hub has delegated admin configured and is enabled in all regions with organization auto-enable', '**AWS Security Hub** has a delegated administrator configured at the organization level, hubs are active in all opted-in regions, and organization auto-enable is active so that new member accounts are automatically enrolled.', 4, NULL, 'Configure a **delegated administrator** for AWS Security Hub via AWS Organizations. Enable Security Hub in **all opted-in regions** and turn on **auto-enable** so new member accounts are automatically enrolled. This ensures uniform security posture monitoring across the entire organization.', 'https://hub.prowler.com/check/securityhub_delegated_admin_enabled_all_regions', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(995, 'aws', 'sns', 'sns_topics_kms_encryption_at_rest_enabled', 'SNS topic is encrypted at rest with KMS', '**Amazon SNS topics** are assessed for **server-side encryption** with **AWS KMS**. Topics lacking a configured KMS key (e.g., missing `kms_master_key_id`) are identified as unencrypted at rest.', 4, NULL, 'Enable **server-side encryption** on all SNS topics with **AWS KMS**; prefer **customer-managed keys** for control.\n\nApply **least privilege** on key use, enforce rotation, and monitor key/access logs. Minimize sensitive data in messages and use end-to-end encryption *where feasible* to add defense in depth.', 'https://hub.prowler.com/check/sns_topics_kms_encryption_at_rest_enabled', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(997, 'aws', 'ssm', 'ssm_document_secrets', 'SSM document contains no secrets', '**AWS Systems Manager documents** are inspected for embedded **secrets** within their content. Patterns resembling passwords, access keys, tokens, or private keys in document steps are flagged when values appear hardcoded rather than referenced securely.', 4, NULL, 'Avoid embedding secrets. Store them in **Secrets Manager** or **Parameter Store** as `SecureString` (KMS-encrypted) and reference at runtime.\n\nApply **least privilege** to documents and secrets, prefer **short-lived role credentials**, rotate credentials, continuously scan/audit documents, and enforce **separation of duties** for authoring and approval.', 'https://hub.prowler.com/check/ssm_document_secrets', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(998, 'aws', 'trustedadvisor', 'trustedadvisor_premium_support_plan_subscribed', 'AWS account is subscribed to an AWS Premium Support plan', '**AWS account** is subscribed to an **AWS Premium Support plan** (e.g., Business or Enterprise)', 2, NULL, 'Adopt **Business** or higher for production and mission-critical accounts.\n- Integrate Support into IR with defined contacts/severity\n- Enforce **least privilege** for case access\n- Use Trusted Advisor for proactive hardening\n- If opting out, ensure an equivalent 24/7 support and escalation path', 'https://hub.prowler.com/check/trustedadvisor_premium_support_plan_subscribed', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1),
(999, 'aws', 'vpc', 'vpc_endpoint_connections_trust_boundaries', 'VPC endpoint policy allows access only from trusted AWS accounts', '**VPC endpoint policies** are assessed for restriction to configured **trusted AWS accounts**. If `Principal` values (including `*`) or account ARNs permit non-trusted principals, or conditions aren\'t sufficiently restrictive, the endpoint is identified. *Endpoints without editable policies are excluded.*', 4, NULL, 'Apply **least privilege**: restrict endpoint policies to your account and an explicit allowlist of **trusted accounts**. Avoid `*` principals unless coupled with strict conditions. Prevent transitive trust across network links, and use resource policies and monitoring as **defense in depth** to limit endpoint use.', 'https://hub.prowler.com/check/vpc_endpoint_connections_trust_boundaries', '2026-08-02 18:29:00', NULL, 0, 'prowler_web', NULL, NULL, '2026-08-02 18:29:00', 1);

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `servicios_aws`
--

CREATE TABLE `servicios_aws` (
  `id` int(11) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `descripcion` varchar(2500) DEFAULT NULL,
  `tipos_servicio_id` int(11) DEFAULT NULL,
  `creacion` datetime DEFAULT current_timestamp(),
  `actualizacion` datetime DEFAULT NULL,
  `estado_id` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Volcado de datos para la tabla `servicios_aws`
--

INSERT INTO `servicios_aws` (`id`, `nombre`, `descripcion`, `tipos_servicio_id`, `creacion`, `actualizacion`, `estado_id`) VALUES
(1, 'S3', 'Auditoría de configuraciones y permisos en buckets S3. Identifica exposición pública, ACL incorrectas y filtración de datos sensibles.', 1, '2026-02-16 23:36:49', NULL, 1),
(2, 'EC2', 'Análisis de instancias y Security Groups en entornos cloud. Detecta puertos expuestos, accesos inseguros y riesgos en metadata service.', 1, '2026-02-16 23:36:49', NULL, 1),
(3, 'IAM', 'Evaluación de políticas, roles y privilegios en la cuenta AWS. Identifica permisos excesivos y posibles escenarios de escalamiento de privilegios.', 1, '2026-02-16 23:36:49', NULL, 1),
(4, 'API Gateway', 'Servicio de exposición y gestión de APIs en AWS.\nPermite auditar endpoints públicos, métodos habilitados, autenticación y configuraciones CORS inseguras.', 1, '2026-02-16 23:36:49', NULL, 1),
(5, 'AWS Lambda', 'Servicio de ejecución serverless que corre código bajo demanda.\nPermite evaluar permisos IAM asociados, exposición de secretos en variables de entorno y riesgos de ejecución no autorizada.Identifica accesibilidad pública, configuraciones débiles y falta de cifrado.', 1, '2026-02-16 23:36:49', NULL, 1),
(6, 'Amazon Inspector', 'Importa y gestiona hallazgos de vulnerabilidades CVE detectados por Amazon Inspector en recursos EC2, Lambda y contenedores.', 1, '2026-05-05 18:22:47', NULL, 1),
(7, 'VPC', 'VPC (Virtual Private Cloud): Audita la configuración de red virtual de AWS (subnets, security groups, rutas) detectando exposición a Internet, reglas de firewall permisivas y falta de segmentación.\nVulnerabilidades conocidas: Security Groups abiertos a 0.0.0.0/0, subnets públicas con recursos sensibles, ausencia de Flow Logs y VPC Peering sin restricción de rutas.', 1, '2026-05-05 18:22:47', NULL, 1),
(8, 'RDS', 'Auditoría de configuraciones y permisos en instancias Amazon RDS, identificando exposición pública, falta de cifrado y debilidades en backups y autenticación.', 1, '2026-06-16 17:01:26', NULL, 1),
(9, 'CloudTrail', 'Auditoría de configuración y estado del servicio de trazabilidad de eventos en AWS.', 1, '2026-06-24 15:46:23', NULL, 1),
(10, 'KMS', 'Auditoría de configuración y estado de claves de cifrado en AWS Key Management Service.', 1, '2026-06-24 16:01:01', NULL, 1),
(11, 'Secrets Manager', 'Auditoría de configuración y estado de secretos en AWS Secrets Manager.', 1, '2026-06-24 16:08:30', NULL, 1);

